import{_ as o,o as t,c as r,a7 as n}from"./chunks/framework.CWfAgRyf.js";const p=JSON.parse('{"title":"Stuck on “Locating server” or at downloading resource packs","description":"Troubleshooting connection problems related to connecting to the server / downloading resource packs.","frontmatter":{"title":"Stuck on “Locating server” or at downloading resource packs","outline":"deep","description":"Troubleshooting connection problems related to connecting to the server / downloading resource packs.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/faq/connecting/stuckduringconnect"}]]},"headers":[],"relativePath":"docs/faq/connecting/stuckduringconnect.md","filePath":"docs/faq/connecting/stuckduringconnect.md","lastUpdated":null}'),a={name:"docs/faq/connecting/stuckduringconnect.md"};function s(c,e,i,l,d,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="stuck-on-locating-server-or-at-downloading-resource-packs" tabindex="-1">Stuck on “Locating server” or at downloading resource packs <a class="header-anchor" href="#stuck-on-locating-server-or-at-downloading-resource-packs" aria-label="Permalink to &quot;Stuck on &quot;Locating server&quot; or at downloading resource packs&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Note</p><p>This page includes some <strong>possible workarounds</strong>. It’s not guaranteed that any of these suggestions will fix your problem.</p></div><h2 id="try-a-different-network" tabindex="-1">Try a different network <a class="header-anchor" href="#try-a-different-network" aria-label="Permalink to &quot;Try a different network&quot;">​</a></h2><p>This usually indicates a problem with your connection. Try using an alternate WiFi network, LAN, mobile data, etc.</p><h2 id="possible-workaround-lower-the-server-s-max-mtu-size" tabindex="-1">Possible workaround: Lower the server’s max MTU size <a class="header-anchor" href="#possible-workaround-lower-the-server-s-max-mtu-size" aria-label="Permalink to &quot;Possible workaround: Lower the server&#39;s max MTU size&quot;">​</a></h2><p>If you consistently have issues connecting to certain servers, sometimes broken MTU size discovery is at fault. This can be caused by an old device, old router, outdated software, or strange network settings.</p><p>If you’re not able to fix this at the source, but you’re able to access the server’s <code>pocketmine.yml</code>, you can try reducing the <code>network.max-mtu-size</code>. Decrease it slowly (e.g. by 100 at a time), and test the server again each time to see if you can connect.</p><p>If you decrease the setting to around 600 and the problem still persists, the issue is likely not the MTU size.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>While reducing the MTU size might enable you to connect, doing so is a <strong>workaround</strong> and will increase the bandwidth usage of your server. The reduced max MTU size will apply to every player, decreasing bandwidth efficiency. You should still try and find and fix the cause of the problem even if lowering the max MTU allows you to connect.</p></div><h2 id="remove-large-resource-packs" tabindex="-1">Remove large resource packs <a class="header-anchor" href="#remove-large-resource-packs" aria-label="Permalink to &quot;Remove large resource packs&quot;">​</a></h2><p>Axolotl-PM is currently known to have problems when using large resource packs on the server.</p><p>If you’re having connection issues when using large packs (e.g. larger than 1 MB), try removing the packs and see if you can connect.</p>',12)])])}const g=o(a,[["render",s]]);export{p as __pageData,g as default};
